// Minimal probe: one ldmatrix.x4 on an 8x8 b16 matrix stored [row][col]
// with rows 16B apart. Print address per lane + fragment registers.
#include <cuda_runtime.h>
#include <cuda_bf16.h>
#include <stdio.h>
#include <stdint.h>

__device__ __forceinline__ void ldmatrix_x4(uint32_t r[4], const void* p) {
    uint32_t a = (uint32_t)__cvta_generic_to_shared(p);
    asm volatile("ldmatrix.sync.aligned.m8n8.x4.shared.b16 {%0,%1,%2,%3}, [%4];\n"
                 : "=r"(r[0]), "=r"(r[1]), "=r"(r[2]), "=r"(r[3]) : "r"(a));
}

// store M[rows 0..31][cols 0..7]: row r = value 1000 + r*8 + c
__global__ void probe(const float* out) {
    __shared__ __nv_bfloat16 sM[32][8];
    int t = threadIdx.x;
    for (int i = t; i < 256; i += 32) {
        int r = i / 8, c = i % 8;
        sM[r][c] = __float2bfloat16((float)(1000 + r * 8 + c));
    }
    __syncthreads();

    int lane = t % 32;
    // 4 matrices: rows 0-7, 8-15, 16-23, 24-31; row r of matrix m at
    // &sM[m*8 + r][0]; lanes provide addr for row (lane%8) of matrix (lane/8).
    uint32_t r[4];
    ldmatrix_x4(r, &sM[(lane / 8) * 8 + lane % 8][0]);

    if (t < 32) {
        uint16_t h[8];
        for (int i = 0; i < 4; i++) { h[2*i] = (uint16_t)(r[i] & 0xffff); h[2*i+1] = (uint16_t)(r[i] >> 16); }
        printf("lane %2d addr_row=%2d: r0={%5d,%5d} r1={%5d,%5d} r2={%5d,%5d} r3={%5d,%5d}\n",
               lane, (lane/8)*8 + lane%8,
               h[0], h[1], h[2], h[3], h[4], h[5], h[6], h[7]);
    }
}

int main() {
    probe<<<1, 32>>>();
    cudaDeviceSynchronize();
    return 0;
}

