1	// Attention forward kernel: FlashAttention-style online softmax, scalar
2	// FP32 pipeline with vectorized (64/128-bit) global and shared memory
3	// accesses. BF16 in/out, FP32 accumulation.
4	//
5	// Work partitioning: one block per (query tile, batch*head). 8 warps per
6	// block; each warp owns ROWS_PER_WARP query rows; within a row the 32 lanes
7	// cover the head dimension with D_PER_LANE consecutive elements each.
8	// BLOCK_M=64 so each K/V tile is reused across 64 query rows (halves
9	// K/V global traffic versus BLOCK_M=32).
10	
11	#include <torch/extension.h>
12	#include <ATen/cuda/CUDAContext.h>
13	#include <c10/cuda/CUDAGuard.h>
14	#include <cuda_bf16.h>
15	#include <math.h>
16	#include <stdint.h>
17	
18	namespace {
19	
20	constexpr int BLOCK_M = 64;   // query rows per block
21	constexpr int BLOCK_N = 64;   // key/value rows per tile
22	constexpr int HEAD_DIM = 128;
23	constexpr int NUM_WARPS = 8;
24	constexpr int NUM_THREADS = NUM_WARPS * 32;
25	constexpr int ROWS_PER_WARP = BLOCK_M / NUM_WARPS;  // 8
26	constexpr int D_PER_LANE = HEAD_DIM / 32;           // 4
27	
28	__device__ __forceinline__ float warp_sum(float v) {
29	#pragma unroll
30	    for (int offset = 16; offset > 0; offset >>= 1)
31	        v += __shfl_xor_sync(0xffffffffu, v, offset);
32	    return v;
33	}
34	
35	__global__ void attention_fwd_kernel(
36	    const __nv_bfloat16* __restrict__ q,
37	    const __nv_bfloat16* __restrict__ k,
38	    const __nv_bfloat16* __restrict__ v,
39	    __nv_bfloat16* __restrict__ out,
40	    int seq_len, float scale, bool causal, int num_heads, int kv_heads)
41	{
42	    const int m_tile = blockIdx.x;
43	    const int bh = blockIdx.y;  // fused batch*head index
44	    const int warp = threadIdx.x / 32;
45	    const int lane = threadIdx.x % 32;
46	    const int d0 = lane * D_PER_LANE;  // first head index of this lane
47	
48	    // GQA: each KV head serves num_heads/kv_heads consecutive query heads.
49	    const int b = bh / num_heads, h = bh % num_heads;
50	    const int kvh = h / (num_heads / kv_heads);
51	    const long long base = ((long long)b * num_heads + h) * seq_len * HEAD_DIM;
52	    const long long base_kv = ((long long)b * kv_heads + kvh) * seq_len * HEAD_DIM;
53	
54	    __shared__ __align__(16) __nv_bfloat16 sK[BLOCK_N][HEAD_DIM];
55	    __shared__ __align__(16) __nv_bfloat16 sV[BLOCK_N][HEAD_DIM];
56	
57	    float q_reg[ROWS_PER_WARP][D_PER_LANE];
58	    float acc[ROWS_PER_WARP][D_PER_LANE];
59	    float row_max[ROWS_PER_WARP];
60	    float row_sum[ROWS_PER_WARP];

